const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const poyang = ee.Geometry.Point([116.2, 29.0]).buffer(30000); // 30km buffer around Poyang Lake
  const date1 = '2022-07-10';
  const date2 = '2022-08-27';

  // 2. Data Acquisition & Check
  const col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(poyang)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(poyang)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`July 10 images: ${size1}`);
  console.log(`August 27 images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('Missing data for one or both dates');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Calculate water area using MNDWI
  function addMNDWI(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudMask = qa.bitwiseAnd(1 << 10).eq(0).and(qa.bitwiseAnd(1 << 11).eq(0));
    return image.updateMask(cloudMask);
  }

  const img1 = col1.map(maskClouds).map(addMNDWI).median();
  const img2 = col2.map(maskClouds).map(addMNDWI).median();

  // Water threshold: MNDWI > 0
  const water1 = img1.select('MNDWI').gt(0);
  const water2 = img2.select('MNDWI').gt(0);

  // 4. Calculate water area
  const area1Stats = water1.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: poyang,
    scale: 3000,
    maxPixels: 1e9
  });

  const area2Stats = water2.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: poyang,
    scale: 3000,
    maxPixels: 1e9
  });

  const pixelCount1 = water1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: poyang,
    scale: 3000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  const pixelCount2 = water2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: poyang,
    scale: 3000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  console.log(`July 10 pixel count: ${pixelCount1}`);
  console.log(`August 27 pixel count: ${pixelCount2}`);

  if (pixelCount1 === 0 || pixelCount2 === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  const area1 = area1Stats.get('MNDWI').getInfo();
  const area2 = area2Stats.get('MNDWI').getInfo();

  // 5. Validation & Final Answer
  if (area1 === null || area2 === null || isNaN(area1) || isNaN(area2)) {
    console.log('Calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  const area1_km2 = (area1 / 1e6).toFixed(2);
  const area2_km2 = (area2 / 1e6).toFixed(2);

  console.log(`July 10 water area: ${area1_km2} km2`);
  console.log(`August 27 water area: ${area2_km2} km2`);
  console.log(`Change: ${(area2 - area1) / 1e6} km2`);

  if (area2 < area1) {
    console.log('Water area decreased');
    console.log('<answer>A</answer>');
  } else {
    console.log('Water area did not decrease');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
